// The signal collectors (docs/PRINCIPLES.md). Each reads a
// bounded, cheap slice of the repo's GitHub state (or local disk) for one signal
// name; `collectSignals` gathers only the union the PICKED task declared, so an
// hourly task never pays for a daily task's signals. Every collector takes the
// shared `(gh, ctx)` and returns a plain data object a precondition reads.
//
// Pure over the injected `gh` reader and a `ctx` of already-resolved facts, so
// the whole layer tests against a fake `gh` with no live GitHub. The ctx facts a
// collector cannot fetch for itself (manifest version, local-pack presence,
// retention) are read off the checkout by signals/context.mjs — see signals/local.mjs.

import { SHARED_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';
import { LOCAL_PACK_ROOT } from './local.mjs';
import {
  QUEUED_LABEL, ORIGIN_AD_HOC, REQUEST_LABEL, STATUS_BLOCKED, STATUS_READY,
  workItemTitle, statusOf, statusesOn, parkKindOf, outcomeOf, parseWorkItemBody,
} from '../queue/work-item.mjs';
import { isQueueItem } from '../queue/read.mjs';
import { APPROVAL_RE } from '../built-in-tasks.mjs';
import { taskFromMessage } from '../task-trailer.mjs';
===
// The commit trailer that says "a scheduled task wrote this", and the reader that
// recognizes it (docs/PRINCIPLES.md).
//
// The silence gate needs to tell the project moving from the machinery running,
// and it must not do so by pattern-matching what a task happened to TITLE its PR:
// every new task's title is then a new leak, discovered only as a task re-armed by
// its own output. So every delivery lane that commits on a task's behalf stamps
// this trailer, and the movement terms read it — the writer classifies its own
// output, so a task added tomorrow is classified correctly on its first run with
// nothing to remember.
//
// It is deliberately the same shape as merge-policy.mjs's `Claudinite-Automerge-Policy`:
// a trailer is what survives a squash merge into the default branch, which is the
// commit the `commits` collector actually reads.

export const TASK_TRAILER = 'Claudinite-Task';

// `Claudinite-Task: <pack>/<task>` on its own line, anywhere in the message.
export const TASK_TRAILER_RE = /^Claudinite-Task:[ \t]*(\S+)[ \t]*$/m;

