/* The 90-day commit curve. `vector-effect` keeps the stroke a hairline through the
   non-uniform viewBox scale — without it a 108-unit box stretched to 108px of a
   26px-tall row draws a line thick horizontally and invisible vertically. */
.commit-graph svg.commits { display: block; width: 100%; height: 26px; }
.commit-area { fill: color-mix(in srgb, var(--good) 22%, transparent); }
.commit-line { fill: none; stroke: var(--good); stroke-width: 1;
               vector-effect: non-scaling-stroke; stroke-linejoin: round; }
.commit-graph .sub { margin-top: 2px; }

/* The pack count wearing the mount's verdict. */
.pack-mark { position: relative; display: inline-block; padding-right: 13px; }
.pack-mark .n { font-size: 19px; line-height: 1.1; }
.pack-mark .badge { position: absolute; top: -1px; right: 0; font-size: 12px; line-height: 1; }
.pack-mark .badge.ok { color: var(--good); }
.pack-mark .badge.info { color: var(--s-blue); }
.pack-mark .badge.serious { color: var(--serious); }

